s=importlib.util.spec_from_file_location('v31_report',V31/'src/report.py');shared=importlib.util.module_from_spec(s);s.loader.exec_module(shared)
LABELS={'h21_original':'Original H21 challenger','monthly_neutral':'Original monthly neutral log growth','monthly_static50':'Original monthly +0.50 beta','daily_neutral':'Daily shared-alpha component only','daily_static25':'Daily fixed +0.25 beta','daily_static50':'Daily fixed +0.50 beta','vol_target':'Volatility-targeted long beta','trend_vol_long':'Trend + volatility, long/neutral','trend_vol_signed':'Trend + volatility, long/short'}
shared.LABELS.update(LABELS);table=shared.table;plt=shared.plt

def main():
    out=HERE/'reports';p=pd.read_csv(out/'performance.csv');q=read(out/'qa.json');status=read(out/'status.json');full=p.loc[p.period.eq('full')].set_index('arm');y22=p.loc[p.period.eq('stress_2022')].set_index('arm');window=p.loc[p.period.eq('drawdown_2021_2023')].set_index('arm')
    order=['h21_original','monthly_neutral','monthly_static50','daily_neutral','daily_static25','daily_static50','vol_target','trend_vol_long','trend_vol_signed'];frame=full.reindex(order).reset_index();frame['return_2022']=frame.arm.map(y22.net_return);frame['dd_2021_2023']=frame.arm.map(window.max_drawdown)
    returns=pd.read_csv(out/'daily_returns.csv.gz',index_col=0,parse_dates=True);td=pd.read_csv(out/'target_diagnostics.csv.gz',parse_dates=['date']);reg=pd.read_csv(out/'regime.csv',index_col=0,parse_dates=True);diagnostics=pd.read_csv(out/'account_diagnostics.csv');growth=pd.read_csv(out/'paired_growth_full.csv');borrow=pd.read_csv(out/'borrow_sensitivity.csv')
    assets=HERE/'assets';assets.mkdir(exist_ok=True);colors={'monthly_static50':'#808792','daily_static50':'#315e87','vol_target':'#d28229','trend_vol_long':'#257c64','trend_vol_signed':'#86539a'};keys=list(colors)
    wealth=(1+returns).cumprod();draw=wealth/wealth.cummax().clip(lower=1)-1
    fig,ax=plt.subplots(figsize=(11,5))
    for a in keys:ax.plot(wealth[a],label=LABELS[a],color=colors[a],lw=1.6,ls='--' if a=='monthly_static50' else '-')
    ax.set(title='Full dataset: 2007–2023',ylabel='Growth of $1 after modeled trading costs');ax.legend(fontsize=8,loc='upper left');fig.tight_layout();fig.savefig(assets/'full_wealth.png',dpi=170);plt.close(fig)
    fig,axs=plt.subplots(2,1,figsize=(11,7),sharex=True)
    for a in keys:
        base=wealth.loc[:'2020-12-31',a].iloc[-1];axs[0].plot(wealth.loc['2021':'2023',a]/base,label=LABELS[a],color=colors[a],lw=1.6,ls='--' if a=='monthly_static50' else '-');axs[1].plot(draw.loc['2021':'2023',a]*100,color=colors[a],lw=1.6,ls='--' if a=='monthly_static50' else '-')
    axs[0].set(title='Around the 2022 drawdown: 2021–2023',ylabel='Wealth, reset to $1 entering 2021');axs[0].legend(fontsize=8,ncol=2,loc='upper left');axs[1].set(ylabel='Drawdown from prior high (%)');fig.tight_layout();fig.savefig(assets/'drawdown_2022.png',dpi=170);plt.close(fig)
    fig,axs=plt.subplots(2,1,figsize=(11,6),sharex=True);axs[0].plot(reg.loc['2021':'2023','sigma']*100,color='#35445a',label='max(21,63-session SPY volatility)');axs[0].axhline(15,color='#999',ls='--');axs[0].set(ylabel='Annualized market volatility (%)',title='Causal signals and beta targets at decision close');axs[0].legend(fontsize=8)
    for a in ['daily_static50','vol_target','trend_vol_long','trend_vol_signed']:
        t=td.loc[td.arm.eq(a)].set_index('date').loc['2021':'2023'];axs[1].plot(t.effective_beta,color=colors[a],label=LABELS[a],lw=1.3)
    axs[1].axhline(0,color='#555',lw=.7);axs[1].set(ylabel='Effective beta target');axs[1].legend(fontsize=8,ncol=2,loc='lower left');fig.tight_layout();fig.savefig(assets/'controller_2022.png',dpi=170);plt.close(fig)
    cols=[('arm','Policy','text'),('cagr','Full CAGR','pct'),('sharpe','Full Sharpe','num'),('volatility','Full volatility','pct'),('max_drawdown','Full max drawdown','pct'),('return_2022','2022 return','pct'),('dd_2021_2023','2021–23 max drawdown','pct')]
    compare=full.loc['daily_static50'];v=full.loc['vol_target'];trend=full.loc['trend_vol_long'];signed=full.loc['trend_vol_signed'];positive='; '.join(LABELS[a]+' versus '+LABELS[b] for a,b in status['positive_growth_holm_both_blocks']) or 'None'
    stress=p.loc[p.period.isin(['stress_2008','stress_2020','stress_2022'])].pivot(index='arm',columns='period',values='net_return').reindex(order).reset_index()
    funding=borrow.loc[borrow.period.eq('full')].pivot(index='arm',columns='annual_borrow_bps',values='cagr').reindex(order).reset_index().rename(columns={0:'zero',100:'one',300:'three'})
    dd=full.reindex(order).reset_index();inf=growth.loc[growth.block_length.eq(60)];diag=diagnostics.loc[diagnostics.period.eq('stress_2022')]
    mechanics='';mfile=out/'mechanics_2022/audit.json'
    if mfile.exists():
        m=read(mfile);sector=pd.read_csv(out/'mechanics_2022/year2022_sectors.csv')
        mechanics=f'<h2>What mechanically failed in2022?</h2><p>An exact holding replay of the original neutral log-growth portfolio reproduces2022 returns with maximum daily error {m["max_2022_return_replay_error"]:.2g}. Its annual return was {m["net_return"]:.2%}: the long book contributed {m["long_net_contribution"]:.2%} of entering capital and the short book {m["short_net_contribution"]:.2%}. Modeled costs were {m["cost"]:.2%} of entering capital and are already included in those contributions.</p><p>The largest losses were technology longs and energy shorts. This is a group-relative exposure that can remain large while SPY beta is near zero. A market-beta controller does not directly remove it. Sector labels below use the last source snapshot available at each position date; Unknown is preserved.</p>'+table(sector,[('sector','Source sector','text'),('net_pnl','Contribution to2022 return','pct'),('long_weight','Average long exposure','pct'),('short_weight','Average short exposure','pct')])+'<p><a href="reports/mechanics_2022/year2022_stocks.csv">Stock-level contributions</a> · <a href="reports/mechanics_2022/january2022_stocks.csv">January holdings attribution</a> · <a href="reports/mechanics_2022/months.csv">Monthly long/short contributions</a> · <a href="reports/mechanics_2022/audit.json">Exact replay audit</a></p>'
    body=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>v33 · Volatility-targeted beta controller</title>
    <style>body{{margin:0;background:#f5f7fa;color:#19283b;font:16px/1.55 system-ui,sans-serif}}main{{max-width:1240px;margin:auto;padding:42px 26px}}h1{{font-size:34px;line-height:1.2}}h2{{margin-top:36px}}p{{max-width:1050px}}.scroll{{overflow-x:auto}}table{{width:100%;border-collapse:collapse;font-size:13px;background:white}}td,th{{padding:9px;border-bottom:1px solid #e2e7ed;white-space:nowrap;text-align:right}}td:first-child,th:first-child{{text-align:left}}thead{{background:#e9eff5}}.note{{padding:16px;background:#fff3dd;border-left:4px solid #bc7b23}}img{{width:100%;height:auto}}a{{color:#245d9b}}code{{overflow-wrap:anywhere;font-size:12px}}</style><main>
    <p>v33 · Full-history test · <a href="../v31_growth_long_bias/index.html">Return objectives and fixed long bias</a> · <a href="../v32_continuous_exposure/index.html">Cash regime and model architecture</a></p>
    <h1>A volatility-targeted beta controller</h1>
    <p>The long-beta request is <strong>min(0.50, 0.075 / market volatility)</strong>. Market volatility is the larger of 21- and 63-session sample estimates, annualized. At 15% volatility the controller permits +0.50 beta; at 30%, +0.25; at 60%, +0.125. All inputs are known at the decision close, and any trade executes no earlier than the next close.</p>
    <p>On the full 2007–2023 sample, the matched daily fixed-50% policy has CAGR {compare.cagr:.2%} and maximum drawdown {compare.max_drawdown:.2%}. Volatility targeting gives {v.cagr:.2%} and {v.max_drawdown:.2%}; adding a long/neutral trend rule gives {trend.cagr:.2%} and {trend.max_drawdown:.2%}; permitting a modest short bias gives {signed.cagr:.2%} and {signed.max_drawdown:.2%}.</p>
    <div class="note">Rules and thresholds were fixed before these account outcomes. The 2022 drawdown was already known and explicitly selected for investigation, so its detailed analysis is retrospective. The full sample is also reused research history. Source valuation qualifications and omitted historical financing remain binding; no automatic promotion or claim of safety.</div>
    <h2>Full dataset and the drawdown around 2022</h2>
    <p>Full CAGR and risk cover 2007–2023. The 2022 column is the actual calendar-year compounded return, not an annualization of a partial window. The last column starts its drawdown calculation entering 2021; the plots additionally show drawdown relative to all previous account history.</p>
    {table(frame,cols)}<img src="assets/full_wealth.png" alt="Full-history wealth paths for fixed and adaptive beta policies">
    <img src="assets/drawdown_2022.png" alt="Wealth and drawdown paths around 2022">{mechanics}
    <h2>What is changing</h2>
    <p>All six new policies use the exact same saved 21-session log-growth forecasts. The stock-selection model is not refitted for this experiment. Risk and beta decisions update daily, with matched daily fixed-25%, fixed-50% and shared-alpha-only controls. The daily fixed-50% target matches the old monthly fixed-50% target on all 204 original forecast dates, so its account difference isolates the intervening daily risk/eligibility updates.</p>
    <p>One common neutral alpha component is derived each day from the fixed-50% reference allocation. Every policy uses that component, subject only to further contraction needed for its joint limits. Reducing beta does not expand the alpha component. Consequently, the shared-alpha-only control is not a separate full-risk neutral strategy; it isolates the alpha budget inside these mixed portfolios.</p>
    <p>The combined forecast-risk ceiling remains 12%, the cohort-adjusted gross cap 3× and the per-name cap 15%. Existing fees, 20% L1 trading buffer, 3.3× gross guard, 0.05 beta/net deviation bands, corporate-event accounting, quote checks and margin rules remain. Target limits do not guarantee that realized risk or intraday exposure stays inside them during a price jump.</p>
    <h2>Direction is separate from volatility</h2>
    <p>A positive state requires the market above its 200-session moving average and a positive 63-session return. A negative state requires both signs reversed; other dates are mixed. The long/neutral version applies 100%, 50% or 0% of the volatility-scaled long request in positive, mixed or negative states. The signed version changes only the negative-state action, allowing up to −0.25 beta, also scaled down in high volatility. A volatility spike alone never creates a short target.</p>
    <p>These are causal rule-based state proxies, not probabilities that the market is safe. Volatility conditioning is motivated by <a href="https://amoreira2.github.io/alan-moreira.github.io/VolPortfolios_published.pdf">Moreira and Muir, Volatility-Managed Portfolios</a>; directional conditioning is motivated by <a href="https://w4.stern.nyu.edu/facdir/lpederse/papers/TimeSeriesMomentum.pdf">Moskowitz, Ooi and Pedersen, Time Series Momentum</a>. This custom inverse-volatility controller and its thresholds are not replications of either paper.</p>
    <img src="assets/controller_2022.png" alt="Market volatility and effective beta requests around 2022">
    <p>Targets above are measured at decision close; fills occur later. The following 2022 diagnostics report actual decision-close estimated beta separately from the target.</p>
    {table(diag,[('arm','Policy','text'),('mean_effective_beta','Mean target beta','num'),('mean_actual_estimated_beta','Mean actual estimated beta','num'),('fraction_short_bias','Days with short target','pct'),('submissions','Trade submissions','num'),('abort_batches','Aborted batches','num'),('margin_calls','Margin calls','num')])}
    <h2>Other stress periods and recovery</h2>{table(stress,[('arm','Policy','text'),('stress_2008','2008 return','pct'),('stress_2020','2020 return','pct'),('stress_2022','2022 return','pct')])}
    {table(dd,[('arm','Policy','text'),('drawdown_peak','Worst-drawdown peak','text'),('drawdown_trough','Trough','text'),('drawdown_recovery','Recovery','text')])}
    <h2>Inference and cost sensitivity</h2><p>The primary endpoint is full-sample annual log growth. Ten fixed paired comparisons use 2,000-draw circular bootstraps and 20/60-session blocks, with Holm adjustment inside this family. Positive growth differences passing both block lengths: <strong>{html.escape(positive)}</strong>. Drawdown differences and stress windows are descriptive, not independently certified protection. Intervals below are pointwise and do not account for earlier project searches.</p>
    {table(inf,[('arm','Candidate','text'),('baseline','Reference','text'),('delta_annual_log_growth','Δ annual log growth','pct'),('ci_low','95% lower','pct'),('ci_high','95% upper','pct'),('p_holm','Holm p','num')])}
    <p>All headline returns include the original 2 bps per-side trading cost and zero borrow/financing/cash yield. The following applies illustrative annual short-borrow charges to prior-close short exposure, holding the trading path fixed. It is not a full funded-account replay or a source of historical borrow availability.</p>
    {table(funding,[('arm','Policy','text'),('zero','0 bp borrow CAGR','pct'),('one','100 bp CAGR','pct'),('three','300 bp CAGR','pct')])}
    <h2>Verification</h2><p>{q['target_vectors']:,} target vectors pass independent risk, net/beta, eligibility and exposure checks. Maximum target constraint error is {q['max_target_constraint_error']:.2g}; maximum forecast volatility is {q['max_forecast_volatility']:.2%}. The no-refill decomposition error is {q['no_refill_decomposition_error']:.2g}. Original covariance parity holds on 204 dates, future-indicator poisoning passes, and execution dates are strictly after decisions. Four focused tests cover causality, signed risk limits, positive-engine identity and short-bias guard/repair behavior. All six accounts pass arithmetic and noncash exposure checks; source performance remains conditional.</p>
    <p><a href="protocol.json">Frozen protocol</a> · <a href="engine_changes.diff">Signed-engine diff</a> · <a href="reports/qa.json">QA audit</a> · <a href="reports/performance.csv">Full and stress-period metrics</a> · <a href="reports/annual.csv">Annual returns</a> · <a href="reports/regime.csv">Regime inputs</a> · <a href="reports/target_diagnostics.csv.gz">Daily target diagnostics</a> · <a href="reports/paired_growth_full.csv">Growth inference</a> · <a href="reports/account_diagnostics.csv">Execution and exposure diagnostics</a></p>
    <p>Protocol SHA-256: <code>{status['protocol_sha256']}</code></p></main></html>'''
    (HERE/'index.html').write_text(body,encoding='utf-8');print(HERE/'index.html')
if __name__=='__main__':main()
